diff --git a/src/features/notes/server/routes.js b/src/features/notes/server/routes.js
index 6ef0b49..90593a5 100644
--- a/src/features/notes/server/routes.js
+++ b/src/features/notes/server/routes.js
@@ -1,20 +1,42 @@
 import { sendJson, readJson } from '../../../lib/http.js';

+const normTag = (t) => t.trim().toLocaleLowerCase('tr');
+
+// Returns the cleaned tag list, or null if the input breaks the rules.
+function parseTags(tags) {
+  if (!Array.isArray(tags) || tags.length > 5) return null;
+  const out = [];
+  for (const t of tags) {
+    if (typeof t !== 'string') return null;
+    const n = normTag(t);
+    if (n.length < 1 || n.length > 20) return null;
+    if (!out.includes(n)) out.push(n);
+  }
+  return out;
+}
+
 // The caller is identified by the x-user header (the auth layer in front of this service sets it).
 export function notesRoutes(store) {
   return async function handle(req, res) {
     const url = new URL(req.url, 'http://localhost');
     const user = req.headers['x-user'];
+    if (url.pathname === '/tags' && req.method === 'GET') return sendJson(res, 200, store.tagCounts(user));
     const match = url.pathname.match(/^\/notes(?:\/([^/]+))?$/);
     if (!match) return false;
     const id = match[1];

-    if (!id && req.method === 'GET') return sendJson(res, 200, store.list());
+    if (!id && req.method === 'GET') {
+      const tag = url.searchParams.get('tag');
+      const notes = store.list();
+      return sendJson(res, 200, tag === null ? notes : notes.filter((n) => n.tags.includes(normTag(tag))));
+    }

     if (!id && req.method === 'POST') {
       const body = await readJson(req);
       if (!body || typeof body.title !== 'string' || !body.title.trim()) return sendJson(res, 400, { error: 'title required' });
-      return sendJson(res, 201, store.create({ owner: user, title: body.title.trim(), body: body.body, createdAt: body.createdAt }));
+      const tags = body.tags === undefined ? [] : parseTags(body.tags);
+      if (!tags) return sendJson(res, 400, { error: 'invalid tags' });
+      return sendJson(res, 201, store.create({ owner: user, title: body.title.trim(), body: body.body, createdAt: body.createdAt, tags }));
     }

     if (id && req.method === 'GET') {
@@ -25,7 +47,9 @@ export function notesRoutes(store) {
     if (id && req.method === 'PATCH') {
       const body = await readJson(req);
       if (!body) return sendJson(res, 400, { error: 'invalid JSON' });
-      const note = store.update(id, { ...(body.title ? { title: body.title } : {}), ...(body.body !== undefined ? { body: body.body } : {}) });
+      const tags = body.tags === undefined ? undefined : parseTags(body.tags);
+      if (tags === null) return sendJson(res, 400, { error: 'invalid tags' });
+      const note = store.update(id, { ...(body.title ? { title: body.title } : {}), ...(body.body !== undefined ? { body: body.body } : {}), ...(tags ? { tags } : {}) });
       return note ? sendJson(res, 200, note) : sendJson(res, 404, { error: 'not found' });
     }

