diff --git a/tests/notes.test.mjs b/tests/notes.test.mjs
index f66308f..8bb21d9 100644
--- a/tests/notes.test.mjs
+++ b/tests/notes.test.mjs
@@ -32,3 +32,134 @@ test('a note can be updated and deleted', async () => {
   assert.equal((await call('DELETE', `/notes/${note.id}`, 'ayse')).status, 204);
   assert.equal((await call('GET', `/notes/${note.id}`, 'ayse')).status, 404);
 });
+
+// ---- tags (AC-T1.x) ----
+const mk = async (user, tags, extra = {}) => {
+  const r = await call('POST', '/notes', user, { title: 'n', ...(tags === undefined ? {} : { tags }), ...extra });
+  return { r, note: r.status === 201 ? await r.clone().json() : null };
+};
+const getNote = async (user, id) => (await call('GET', `/notes/${id}`, user)).json();
+
+test('AC-T1.1 POST accepts tags and returns them', async () => {
+  const { r, note } = await mk('t1a', ['work', 'home']);
+  assert.equal(r.status, 201);
+  assert.deepEqual(note.tags, ['work', 'home']);
+  assert.deepEqual((await getNote('t1a', note.id)).tags, ['work', 'home']);
+});
+
+test('AC-T1.2 note without tags has tags []', async () => {
+  const { note } = await mk('t1b');
+  assert.deepEqual(note.tags, []);
+  assert.deepEqual((await getNote('t1b', note.id)).tags, []);
+});
+
+test('AC-T1.3 tags are trimmed and lowercased with Turkish rules', async () => {
+  const { note } = await mk('t1c', ['  İŞ ', 'IŞIK', 'Istanbul', 'İzmir']);
+  assert.deepEqual(note.tags, ['iş', 'ışık', 'ıstanbul', 'izmir']);
+});
+
+test('AC-T1.4 duplicates dropped after normalizing, first-seen order kept', async () => {
+  const { note } = await mk('t1d', ['b', 'İŞ', 'a', 'iş', ' B ']);
+  assert.deepEqual(note.tags, ['b', 'iş', 'a']);
+  const { note: n2 } = await mk('t1d', ['IŞ', 'ış', 'İŞ']);
+  assert.deepEqual(n2.tags, ['ış', 'iş']);
+});
+
+test('AC-T1.5 boundaries: 5 tags and 20-char tag accepted (20 after trim)', async () => {
+  const { r, note } = await mk('t1e', ['a', 'b', 'c', 'd', ' ' + 'x'.repeat(20) + ' ']);
+  assert.equal(r.status, 201);
+  assert.deepEqual(note.tags, ['a', 'b', 'c', 'd', 'x'.repeat(20)]);
+});
+
+test('AC-T1.6 POST rejects invalid tags with 400', async () => {
+  const bad = [
+    'work', { a: 1 }, null, 5,
+    [1], ['ok', null], [['x']], [{}],
+    [''], ['   '], ['ok', ''],
+    ['x'.repeat(21)], [' ' + 'x'.repeat(21) + ' '],
+    ['a', 'b', 'c', 'd', 'e', 'f'],
+    ['a', 'a', 'a', 'a', 'a', 'a'], // 6 on input, even though only 1 unique
+  ];
+  for (const tags of bad) {
+    const { r } = await mk('t1f', tags);
+    assert.equal(r.status, 400, `expected 400 for ${JSON.stringify(tags)}`);
+  }
+});
+
+test('AC-T1.7 PATCH replaces tags', async () => {
+  const { note } = await mk('t1g', ['old', 'keep']);
+  const r = await call('PATCH', `/notes/${note.id}`, 't1g', { tags: ['New', 'IŞ'] });
+  assert.equal(r.status, 200);
+  assert.deepEqual((await r.json()).tags, ['new', 'ış']);
+  assert.deepEqual((await getNote('t1g', note.id)).tags, ['new', 'ış']);
+});
+
+test('AC-T1.8 PATCH without tags leaves them; PATCH [] clears', async () => {
+  const { note } = await mk('t1h', ['one', 'two']);
+  const r1 = await call('PATCH', `/notes/${note.id}`, 't1h', { title: 'renamed' });
+  assert.deepEqual((await r1.json()).tags, ['one', 'two']);
+  const r2 = await call('PATCH', `/notes/${note.id}`, 't1h', { tags: [] });
+  assert.equal(r2.status, 200);
+  assert.deepEqual((await r2.json()).tags, []);
+  assert.deepEqual((await getNote('t1h', note.id)).tags, []);
+});
+
+test('AC-T1.9 PATCH with invalid tags is 400 and note unchanged', async () => {
+  const { note } = await mk('t1i', ['keep']);
+  const bad = ['x', [1], [''], ['  '], ['x'.repeat(21)], ['a', 'b', 'c', 'd', 'e', 'f'], ['a', 'a', 'a', 'a', 'a', 'a'], null];
+  for (const tags of bad) {
+    const r = await call('PATCH', `/notes/${note.id}`, 't1i', { title: 'changed', tags });
+    assert.equal(r.status, 400, `expected 400 for ${JSON.stringify(tags)}`);
+  }
+  const got = await getNote('t1i', note.id);
+  assert.deepEqual(got.tags, ['keep']);
+  assert.equal(got.title, 'n');
+});
+
+test('AC-T1.10 GET /notes?tag= filters, case-insensitive with Turkish rules', async () => {
+  const a = (await mk('t1j', ['İşzz', 'zzfolt1'])).note;
+  const b = (await mk('t1j', ['zzfolt1'])).note;
+  const c = (await mk('t1j', ['other'])).note;
+  const ids = async (q) => (await (await call('GET', `/notes?tag=${encodeURIComponent(q)}`, 't1j')).json()).map((n) => n.id);
+  assert.deepEqual((await ids('ZZFOLT1')).sort(), [a.id, b.id].sort());
+  assert.deepEqual(await ids('İŞZZ'), [a.id]);
+  assert.deepEqual(await ids('işzz'), [a.id]);
+  assert.equal((await ids('işzz')).includes(c.id), false);
+  assert.deepEqual(await ids('nonexistent-zz'), []);
+});
+
+test('AC-T1.11 GET /tags counts, sorted by count desc then alphabetical', async () => {
+  const u = 't1k';
+  await mk(u, ['iş', 'zeta', 'alfa']);
+  await mk(u, ['İŞ', 'beta']);
+  await mk(u, ['alfa', 'beta']);
+  await mk(u, ['gama', 'iş']);
+  const r = await call('GET', '/tags', u);
+  assert.equal(r.status, 200);
+  assert.deepEqual(await r.json(), [
+    { tag: 'iş', count: 3 },
+    { tag: 'alfa', count: 2 },
+    { tag: 'beta', count: 2 },
+    { tag: 'gama', count: 1 },
+    { tag: 'zeta', count: 1 },
+  ]);
+});
+
+test('AC-T1.12 GET /tags ignores other users and is [] without tags', async () => {
+  await mk('t1l', ['secret-l']);
+  await mk('t1m', ['mine-m']);
+  await mk('t1n');
+  assert.deepEqual(await (await call('GET', '/tags', 't1m')).json(), [{ tag: 'mine-m', count: 1 }]);
+  assert.deepEqual(await (await call('GET', '/tags', 't1n')).json(), []);
+  assert.deepEqual(await (await call('GET', '/tags', 't1-never-posted')).json(), []);
+});
+
+test('AC-T1.13 GET /tags reflects PATCH and DELETE', async () => {
+  const { note } = await mk('t1o', ['a', 'b']);
+  await call('PATCH', `/notes/${note.id}`, 't1o', { tags: ['b', 'c'] });
+  assert.deepEqual(await (await call('GET', '/tags', 't1o')).json(), [
+    { tag: 'b', count: 1 }, { tag: 'c', count: 1 },
+  ]);
+  await call('DELETE', `/notes/${note.id}`, 't1o');
+  assert.deepEqual(await (await call('GET', '/tags', 't1o')).json(), []);
+});

