diff --git a/tests/tags.test.mjs b/tests/tags.test.mjs
new file mode 100644
index 0000000..2961e90
--- /dev/null
+++ b/tests/tags.test.mjs
@@ -0,0 +1,175 @@
+import { test, before, after } from 'node:test';
+import assert from 'node:assert/strict';
+import { createApp } from '../src/app/server.js';
+
+let server, base;
+before(async () => {
+  server = createApp().listen(0);
+  await new Promise((r) => server.once('listening', r));
+  base = `http://127.0.0.1:${server.address().port}`;
+});
+after(() => server.close());
+
+const call = (method, path, user, body) => fetch(base + path, {
+  method, headers: { 'content-type': 'application/json', ...(user ? { 'x-user': user } : {}) }, body: body && JSON.stringify(body),
+});
+const mk = async (user, tags, title = 'n') => {
+  const r = await call('POST', '/notes', user, tags === undefined ? { title } : { title, tags });
+  assert.equal(r.status, 201);
+  return r.json();
+};
+
+const invalid = {
+  'non-array (string)': 'work',
+  'non-array (object)': { a: 1 },
+  'non-string item (number)': ['ok', 5],
+  'non-string item (null)': [null],
+  'empty item': [''],
+  'whitespace-only item': ['   '],
+  '21 chars': ['a'.repeat(21)],
+  '21 chars after trim is still too long': ['  ' + 'a'.repeat(21) + '  '],
+  '6 tags': ['a', 'b', 'c', 'd', 'e', 'f'],
+};
+
+for (const [name, tags] of Object.entries(invalid)) {
+  test(`AC-01.1 POST rejects tags: ${name}`, async () => {
+    assert.equal((await call('POST', '/notes', 'v-post', { title: 't', tags })).status, 400);
+  });
+  test(`AC-01.1 PATCH rejects tags: ${name}`, async () => {
+    const n = await mk('v-patch', ['keep']);
+    assert.equal((await call('PATCH', `/notes/${n.id}`, 'v-patch', { tags })).status, 400);
+    const got = await (await call('GET', `/notes/${n.id}`, 'v-patch')).json();
+    assert.deepEqual(got.tags, ['keep']);
+  });
+}
+
+test('AC-01.1 20-char tag and 5 tags are accepted on POST and PATCH', async () => {
+  const twenty = 'a'.repeat(20);
+  const r = await call('POST', '/notes', 'ok-1', { title: 't', tags: [twenty] });
+  assert.equal(r.status, 201);
+  assert.deepEqual((await r.json()).tags, [twenty]);
+  const five = ['a', 'b', 'c', 'd', 'e'];
+  const r2 = await call('POST', '/notes', 'ok-1', { title: 't', tags: five });
+  assert.equal(r2.status, 201);
+  assert.deepEqual((await r2.json()).tags, five);
+  const n = await mk('ok-1');
+  const p = await call('PATCH', `/notes/${n.id}`, 'ok-1', { tags: five });
+  assert.equal(p.status, 200);
+  assert.deepEqual((await p.json()).tags, five);
+  const p2 = await call('PATCH', `/notes/${n.id}`, 'ok-1', { tags: [` ${twenty} `] });
+  assert.equal(p2.status, 200);
+  assert.deepEqual((await p2.json()).tags, [twenty]);
+});
+
+test('AC-01.2 Turkish lowercase: İŞ -> iş, I -> ı', async () => {
+  const n = await mk('tr-1', ['İŞ', 'ISIK', 'I']);
+  assert.deepEqual(n.tags, ['iş', 'ısık', 'ı']);
+  const got = await (await call('GET', `/notes/${n.id}`, 'tr-1')).json();
+  assert.deepEqual(got.tags, ['iş', 'ısık', 'ı']);
+});
+
+test('AC-01.2 tags are trimmed', async () => {
+  const n = await mk('tr-2', ['  work ', '\tHome\n']);
+  assert.deepEqual(n.tags, ['work', 'home']);
+});
+
+test('AC-01.2 duplicates dropped, including case variants, first-seen order kept', async () => {
+  const n = await mk('tr-3', ['b', 'İş', 'a', 'iş', 'B', 'İŞ', ' a ']);
+  assert.deepEqual(n.tags, ['b', 'iş', 'a']);
+});
+
+test('AC-01.2 Turkish I and i stay distinct tags; I and ı are duplicates', async () => {
+  const n = await mk('tr-4', ['I', 'i', 'ı']);
+  assert.deepEqual(n.tags, ['ı', 'i']);
+});
+
+test('AC-01.2 normalization also applies on PATCH', async () => {
+  const n = await mk('tr-5');
+  const p = await (await call('PATCH', `/notes/${n.id}`, 'tr-5', { tags: [' İŞ ', 'iş', 'Z'] })).json();
+  assert.deepEqual(p.tags, ['iş', 'z']);
+});
+
+test('AC-01.3 note without tags has tags [] on POST, GET one and GET list', async () => {
+  const n = await mk('def-1');
+  assert.deepEqual(n.tags, []);
+  const got = await (await call('GET', `/notes/${n.id}`, 'def-1')).json();
+  assert.deepEqual(got.tags, []);
+  const list = await (await call('GET', '/notes', 'def-1')).json();
+  const mine = list.filter((x) => x.id === n.id);
+  assert.equal(mine.length, 1);
+  assert.deepEqual(mine[0].tags, []);
+});
+
+test('AC-01.3 PATCH tags replaces, omitted keeps, [] clears', async () => {
+  const n = await mk('rep-1', ['a', 'b']);
+  const id = n.id;
+  let p = await (await call('PATCH', `/notes/${id}`, 'rep-1', { tags: ['c'] })).json();
+  assert.deepEqual(p.tags, ['c']);
+  p = await (await call('PATCH', `/notes/${id}`, 'rep-1', { title: 'renamed' })).json();
+  assert.equal(p.title, 'renamed');
+  assert.deepEqual(p.tags, ['c']);
+  assert.deepEqual((await (await call('GET', `/notes/${id}`, 'rep-1')).json()).tags, ['c']);
+  p = await (await call('PATCH', `/notes/${id}`, 'rep-1', { tags: [] })).json();
+  assert.deepEqual(p.tags, []);
+  assert.deepEqual((await (await call('GET', `/notes/${id}`, 'rep-1')).json()).tags, []);
+});
+
+test('AC-01.4 ?tag= filters notes, case-insensitive with Turkish rules', async () => {
+  const a = await mk('flt-1', ['flt1-iş', 'flt1-x'], 'A');
+  const b = await mk('flt-1', ['flt1-x'], 'B');
+  const c = await mk('flt-1', undefined, 'C');
+  const only = async (q) => (await (await call('GET', `/notes?tag=${encodeURIComponent(q)}`, 'flt-1')).json()).map((n) => n.id);
+  assert.deepEqual(await only('flt1-iş'), [a.id]);
+  assert.deepEqual(await only('FLT1-İŞ'), [a.id]);
+  assert.deepEqual(await only('Flt1-İş'), [a.id]);
+  const x = await only('flt1-x');
+  assert.deepEqual(x.filter((id) => [a.id, b.id, c.id].includes(id)).sort(), [a.id, b.id].sort());
+  assert.deepEqual(await only('flt1-nope'), []);
+});
+
+test('AC-01.4 ?tag=KIL matches stored kıl-style tag by Turkish rules, not kil', async () => {
