+});
+after(() => server.close());
+
+const call = (method, path, user, body) => fetch(base + path, {
+  method, headers: { 'content-type': 'application/json', ...(user ? { 'x-user': user } : {}) }, body: body && JSON.stringify(body),
+});
+
+let seq = 0;
+const newUser = (name) => `${name}-${++seq}-${Math.random().toString(36).slice(2, 8)}`;
+
+async function createNote(user, fields) {
+  const r = await call('POST', '/notes', user, { title: 'Note', ...fields });
+  assert.equal(r.status, 201, `create failed for ${JSON.stringify(fields)}`);
+  return r.json();
+}
+const getNote = async (user, id) => (await call('GET', `/notes/${id}`, user)).json();
+const byTag = async (user, tag) => {
+  const r = await call('GET', `/notes?tag=${encodeURIComponent(tag)}`, user);
+  assert.equal(r.status, 200);
+  return r.json();
+};
+const ids = (notes) => notes.map((n) => n.id).sort();
+
+const TWENTY = 'abcdefghijklmnopqrst';
+const TWENTY_ONE = TWENTY + 'u';
+
+// Every case here breaks a tag rule; POST and PATCH must both answer 400.
+const INVALID_TAGS = [
+  ['a string instead of an array', 'iş'],
+  ['an object instead of an array', { 0: 'iş' }],
+  ['a number instead of an array', 5],
