+  assert.deepEqual((await getNote(user, note.id)).tags, ['iş', 'ı', 'i', 'ışık', 'çğöü']);
+});
+
+test('AC-01.2 a 20-char tag of İ is accepted and lowercases to 20 single-char i (not i + combining dot)', async () => {
