diff --git a/src/features/notes/server/tags.js b/src/features/notes/server/tags.js
new file mode 100644
index 0000000..42b6ea7
--- /dev/null
+++ b/src/features/notes/server/tags.js
@@ -0,0 +1,29 @@
+const MAX_TAGS = 5;
+const MAX_LENGTH = 20;
+
+const lower = (s) => s.toLocaleLowerCase('tr');
+
+// Returns the cleaned tag list, or null when the input breaks the rules.
+export function normalizeTags(input) {
+  if (!Array.isArray(input)) return null;
+  const tags = new Set();
+  for (const item of input) {
+    if (typeof item !== 'string') return null;
+    const tag = lower(item.trim());
+    if (!tag || tag.length > MAX_LENGTH) return null;
+    tags.add(tag);
+  }
+  return tags.size <= MAX_TAGS ? [...tags] : null;
+}
+
+export function hasTag(note, tag) {
+  return note.tags.includes(lower(tag.trim()));
+}
+
+export function countTags(notes) {
+  const counts = new Map();
+  for (const note of notes) for (const tag of note.tags) counts.set(tag, (counts.get(tag) ?? 0) + 1);
+  return [...counts]
+    .map(([tag, count]) => ({ tag, count }))
+    .sort((a, b) => b.count - a.count || a.tag.localeCompare(b.tag, 'tr'));
+}
