+  headers: { 'content-type': 'application/json', ...(user === undefined ? {} : { 'x-user': user }) },
+  body: body && JSON.stringify(body),
+});
+
+const mk = async (user, title) => (await call('POST', '/notes', user, { title, body: 'b' })).json();
+
+const routes = (id) => [
+  ['GET', '/notes'],
