+    assert.equal((await call(m, p, undefined, b)).status, 401, `${m} ${p}`);
+  }
+  // nothing was changed by the anonymous attempts
+  const got = await (await call('GET', `/notes/${note.id}`, 'owner-a')).json();
+  assert.equal(got.title, 'secret');
+});
+
+test('AC-01.2 empty x-user -> 401 on every route', async () => {
+  const note = await mk('owner-b', 'secret');
+  for (const [m, p, b] of routes(note.id)) {
+    assert.equal((await call(m, p, '', b)).status, 401, `${m} ${p}`);
+  }
+});
+
+test('AC-01.2 whitespace-only x-user -> 401 on every route', async () => {
+  const note = await mk('owner-c', 'secret');
+  for (const [m, p, b] of routes(note.id)) {
