+  const mine = await create('ac11-ali', 'mine');
+  const theirs = await create('ac11-veli', 'theirs');
+  const r = await call('GET', '/notes', 'ac11-ali');
+  assert.equal(r.status, 200);
+  const list = await r.json();
+  assert.ok(Array.isArray(list));
