+  assert.equal(r.status, 404);
+  assert.equal(JSON.stringify(await r.json()).includes('secret'), false);
+});
+
+test('AC-01.3 PATCH /notes/:id of another user note is 404 and owner copy unchanged', async () => {
+  const note = await create('ac13-ali', 'original');
+  const r = await call('PATCH', `/notes/${note.id}`, 'ac13-veli', { title: 'hacked', body: 'hacked' });
+  assert.equal(r.status, 404);
+  const got = await (await call('GET', `/notes/${note.id}`, 'ac13-ali')).json();
+  assert.equal(got.title, 'original');
+  assert.equal(got.body, 'b');
+});
+
+test('AC-01.4 DELETE /notes/:id of another user note is 404 and note still exists', async () => {
+  const note = await create('ac14-ali', 'keep');
+  const r = await call('DELETE', `/notes/${note.id}`, 'ac14-veli');
+  assert.equal(r.status, 404);
